import { STORE_NAMES, type StoreName } from "../db/schema";
import type { StoredFile } from "../db/types";

export const BACKUP_FORMAT = "local-career-workspace-backup" as const;
export const BACKUP_VERSION = 1 as const;
export type BackupKind = "light" | "full";

export interface EncodedOriginalFile {
  id: string;
  createdAt: string;
  updatedAt: string;
  ownerType: StoredFile["ownerType"];
  ownerId: string;
  fileName: string;
  fileType: StoredFile["fileType"];
  mimeType: string;
  size: number;
  bytes: string;
}

export type BackupStores = Partial<Record<Exclude<StoreName, "sensitiveSettings" | "originalFiles">, unknown[]>> & {
  originalFiles?: never;
};

export interface BackupPayload {
  kind: BackupKind;
  exportedAt: string;
  stores: BackupStores;
  originalFiles?: EncodedOriginalFile[];
}

export interface BackupEnvelope {
  format: typeof BACKUP_FORMAT;
  version: typeof BACKUP_VERSION;
  kind: BackupKind;
  salt: string;
  iv: string;
  kdf: { name: "PBKDF2"; hash: "SHA-256"; iterations: number; salt: string };
  cipher: { name: "AES-GCM"; iv: string; tagLength: 128 };
  ciphertext: string;
}

const ALLOWED_STORES = Object.values(STORE_NAMES).filter(
  (name): name is Exclude<StoreName, "sensitiveSettings" | "originalFiles"> =>
    name !== STORE_NAMES.sensitiveSettings && name !== STORE_NAMES.originalFiles,
);

export function allowedBackupStores(): readonly Exclude<StoreName, "sensitiveSettings" | "originalFiles">[] {
  return ALLOWED_STORES;
}

function isBase64(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && value.length % 4 === 0 && /^[A-Za-z0-9+/]*={0,2}$/.test(value);
}

function decodedByteLength(value: string): number {
  const padding = value.endsWith("==") ? 2 : value.endsWith("=") ? 1 : 0;
  return (value.length * 3) / 4 - padding;
}

function isIso(value: unknown): value is string {
  return typeof value === "string" && Number.isFinite(Date.parse(value));
}

export function validateBackupEnvelope(value: unknown): asserts value is BackupEnvelope {
  if (!value || typeof value !== "object") throw new Error("Invalid backup envelope");
  const envelope = value as Record<string, unknown>;
  if (envelope.format !== BACKUP_FORMAT) throw new Error("Invalid backup format");
  if (envelope.version !== BACKUP_VERSION) throw new Error("Unsupported backup version");
  if (envelope.kind !== "light" && envelope.kind !== "full") throw new Error("Invalid backup kind");
  if (!isBase64(envelope.ciphertext) || !isBase64(envelope.salt) || !isBase64(envelope.iv)) throw new Error("Invalid backup ciphertext");
  const kdf = envelope.kdf as Record<string, unknown> | undefined;
  if (!kdf || kdf.name !== "PBKDF2" || kdf.hash !== "SHA-256" || typeof kdf.iterations !== "number" || !Number.isInteger(kdf.iterations) || kdf.iterations < 100_000 || !isBase64(kdf.salt)) {
    throw new Error("Invalid backup KDF parameters");
  }
  const cipher = envelope.cipher as Record<string, unknown> | undefined;
  if (!cipher || cipher.name !== "AES-GCM" || cipher.tagLength !== 128 || !isBase64(cipher.iv)) throw new Error("Invalid backup cipher parameters");
  if (kdf.salt !== envelope.salt || cipher.iv !== envelope.iv) throw new Error("Invalid backup parameter metadata");
}

function validateRecordArray(value: unknown, storeName: string): unknown[] {
  if (!Array.isArray(value)) throw new Error(`Invalid backup store: ${storeName}`);
  for (const record of value) {
    if (!record || typeof record !== "object") throw new Error(`Invalid record in store: ${storeName}`);
    const item = record as Record<string, unknown>;
    if (typeof item.id !== "string" || !item.id || !isIso(item.createdAt) || !isIso(item.updatedAt)) throw new Error(`Invalid record in store: ${storeName}`);
  }
  return value;
}

export function validateBackupPayload(value: unknown, expectedKind?: BackupKind): asserts value is BackupPayload {
  if (!value || typeof value !== "object") throw new Error("Invalid backup payload");
  const payload = value as Record<string, unknown>;
  if (payload.kind !== "light" && payload.kind !== "full") throw new Error("Invalid backup payload kind");
  if (expectedKind && payload.kind !== expectedKind) throw new Error("Backup kind mismatch");
  if (!isIso(payload.exportedAt)) throw new Error("Invalid backup export timestamp");
  if (!payload.stores || typeof payload.stores !== "object" || Array.isArray(payload.stores)) throw new Error("Invalid backup stores");
  const stores = payload.stores as Record<string, unknown>;
  for (const key of Object.keys(stores)) {
    if (!ALLOWED_STORES.includes(key as (typeof ALLOWED_STORES)[number])) throw new Error(`Disallowed backup store: ${key}`);
    validateRecordArray(stores[key], key);
  }
  if (payload.kind === "light" && Object.prototype.hasOwnProperty.call(payload, "originalFiles")) throw new Error("Light backup cannot contain originalFiles");
  if (payload.kind === "full") {
    if (!Array.isArray(payload.originalFiles)) throw new Error("Full backup missing originalFiles");
    for (const file of payload.originalFiles) {
      if (!file || typeof file !== "object") throw new Error("Invalid original file record");
      const item = file as Record<string, unknown>;
      if (typeof item.id !== "string" || !item.id || !isIso(item.createdAt) || !isIso(item.updatedAt) || (item.ownerType !== "resume" && item.ownerType !== "job-description") || typeof item.ownerId !== "string" || typeof item.fileName !== "string" || (item.fileType !== "pdf" && item.fileType !== "docx") || typeof item.mimeType !== "string" || typeof item.size !== "number" || !Number.isInteger(item.size) || item.size < 0 || !isBase64(item.bytes) || decodedByteLength(item.bytes) !== item.size) throw new Error(`Invalid original file record: ${JSON.stringify(item)}`);
    }
  }
}
import { requestToPromise, runTransaction } from "../db/database";
import { STORE_NAMES } from "../db/schema";
import type { StoredFile } from "../db/types";
import {
  BACKUP_FORMAT,
  BACKUP_VERSION,
  allowedBackupStores,
  type BackupEnvelope,
  type BackupKind,
  type BackupPayload,
  type EncodedOriginalFile,
  validateBackupEnvelope,
  validateBackupPayload,
} from "./format";

const PBKDF2_ITERATIONS = 210_000;
const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder();

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(binary);
}

function base64ToBytes(value: string): Uint8Array {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

async function deriveKey(password: string, salt: Uint8Array): Promise<CryptoKey> {
  if (typeof password !== "string" || password.length === 0) throw new Error("Backup password is required");
  const material = await crypto.subtle.importKey("raw", textEncoder.encode(password), "PBKDF2", false, ["deriveKey"]);
  return crypto.subtle.deriveKey({ name: "PBKDF2", salt: salt as BufferSource, iterations: PBKDF2_ITERATIONS, hash: "SHA-256" }, material, { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
}

async function blobBytes(blob: Blob): Promise<Uint8Array> {
  if (typeof blob.arrayBuffer === "function") return new Uint8Array(await blob.arrayBuffer());
  if (typeof (blob as Blob & { text?: () => Promise<string> }).text === "function") {
    return textEncoder.encode(await (blob as Blob & { text: () => Promise<string> }).text());
  }
  return new Uint8Array(await new Response(blob).arrayBuffer());
}

async function readStores(database: IDBDatabase, kind: BackupKind): Promise<BackupPayload> {
  const storeNames = [...allowedBackupStores(), ...(kind === "full" ? [STORE_NAMES.originalFiles] : [])] as const;
  const result = await runTransaction(database, storeNames, "readonly", async (tx) => {
    const stores: Record<string, unknown[]> = {};
    for (const storeName of allowedBackupStores()) stores[storeName] = await requestToPromise<unknown[]>(tx.objectStore(storeName).getAll());
    let originalFiles: EncodedOriginalFile[] | undefined;
    if (kind === "full") {
      const files = await requestToPromise<StoredFile[]>(tx.objectStore(STORE_NAMES.originalFiles).getAll());
      originalFiles = [];
      for (const file of files) {
        const bytes = await blobBytes(file.blob);
        originalFiles.push({ id: file.id, createdAt: file.createdAt, updatedAt: file.updatedAt, ownerType: file.ownerType, ownerId: file.ownerId, fileName: file.fileName, fileType: file.fileType, mimeType: file.blob.type, size: bytes.byteLength, bytes: bytesToBase64(bytes) });
      }
    }
    return { kind, exportedAt: new Date().toISOString(), stores, ...(originalFiles ? { originalFiles } : {}) } as BackupPayload;
  });
  validateBackupPayload(result, kind);
  return result;
}

export async function exportBackup(database: IDBDatabase, options: { kind: BackupKind; password: string }): Promise<BackupEnvelope> {
  const payload = await readStores(database, options.kind);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await deriveKey(options.password, salt);
  const ciphertext = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv: iv as BufferSource, tagLength: 128 }, key, textEncoder.encode(JSON.stringify(payload))));
  const saltBase64 = bytesToBase64(salt);
  const ivBase64 = bytesToBase64(iv);
  return { format: BACKUP_FORMAT, version: BACKUP_VERSION, kind: options.kind, salt: saltBase64, iv: ivBase64, kdf: { name: "PBKDF2", hash: "SHA-256", iterations: PBKDF2_ITERATIONS, salt: saltBase64 }, cipher: { name: "AES-GCM", iv: ivBase64, tagLength: 128 }, ciphertext: bytesToBase64(ciphertext) };
}

export async function decryptBackup(input: unknown, password: string): Promise<BackupPayload> {
  validateBackupEnvelope(input);
  try {
    const key = await deriveKey(password, base64ToBytes(input.salt));
    const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: base64ToBytes(input.iv) as BufferSource, tagLength: 128 }, key, base64ToBytes(input.ciphertext) as BufferSource);
    const payload: unknown = JSON.parse(textDecoder.decode(plain));
    validateBackupPayload(payload, input.kind);
    return payload;
  } catch (error) {
    if (error instanceof Error && /Invalid backup|Unsupported backup|mismatch/.test(error.message)) throw error;
    throw new Error("Unable to decrypt backup");
  }
}

